#include "../ring3_common.hpp"
// Pebble: local-first micro-friction ledger. Capture small recurring annoyances before they disappear.
static constexpr u32 W=780,H=540; static u32*pix; static u64 events,win; static bool dirty=true;
static int field=0,scroll=0; static char friction[100]={0},context[90]={0},fixidea[100]={0},minutes[8]={0}; static u32 fl=0,cl=0,xl=0,ml=0; static char logbuf[2200]={0}; static u32 debt=0,entries=0;
static u32 slen(const char*s){u32 n=0;while(s&&s[n])n++;return n;} static void cat(char*d,u32 cap,const char*s){u32 n=slen(d),i=0;while(s&&s[i]&&n+1<cap)d[n++]=s[i++];d[n]=0;}
static void num(char*out,u32 v){char t[12];u32 n=0;if(!v){out[0]='0';out[1]=0;return;}while(v&&n<11){t[n++]=(char)('0'+v%10);v/=10;}u32 z=0;while(n)out[z++]=t[--n];out[z]=0;}
static u32 parsemin(){u32 v=0;for(u32 i=0;i<ml;i++)if(minutes[i]>='0'&&minutes[i]<='9')v=v*10+(u32)(minutes[i]-'0');return v;}
static void rr(i32 x,i32 y,i32 w,i32 h,i32 r,u32 c){rect(pix,W,H,x+r,y,w-2*r,h,c);rect(pix,W,H,x,y+r,w,h-2*r,c);for(i32 yy=0;yy<r;yy++)for(i32 xx=0;xx<r;xx++){i32 dx=r-xx-1,dy=r-yy-1;if(dx*dx+dy*dy<=r*r){rect(pix,W,H,x+xx,y+yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+yy,1,1,c);rect(pix,W,H,x+xx,y+h-1-yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+h-1-yy,1,1,c);}}}
static void summarize(){debt=entries=0;const char*m="MINUTES | ";for(u32 i=0;logbuf[i];i++){u32 j=0;while(m[j]&&logbuf[i+j]==m[j])j++;if(!m[j]){i+=j;u32 v=0;while(logbuf[i]>='0'&&logbuf[i]<='9'){v=v*10+(u32)(logbuf[i]-'0');i++;}debt+=v;entries++;}}}
static void load(){for(u32 i=0;i<sizeof(logbuf);i++)logbuf[i]=0;i64 h=sc(32,(u64)"/Home/Documents/PEBBLE.LOG",1);if(h>0){i64 n=sc(33,(u64)h,(u64)logbuf,sizeof(logbuf)-1);if(n>0&&n<(i64)sizeof(logbuf))logbuf[n]=0;sc(35,(u64)h);}summarize();dirty=true;}
static void save(){if(!fl)return;char line[520]={0};cat(line,sizeof(line),"FRICTION| ");cat(line,sizeof(line),friction);cat(line,sizeof(line),"\nCONTEXT | ");cat(line,sizeof(line),context);cat(line,sizeof(line),"\nMINUTES | ");cat(line,sizeof(line),ml?minutes:"1");cat(line,sizeof(line),"\nFIX IDEA| ");cat(line,sizeof(line),fixidea);cat(line,sizeof(line),"\n---\n");i64 h=sc(32,(u64)"/Home/Documents/PEBBLE.LOG",2|4);if(h>0){sc(34,(u64)h,(u64)line,slen(line));sc(35,(u64)h);}friction[0]=context[0]=fixidea[0]=minutes[0]=0;fl=cl=xl=ml=0;field=0;load();}
static void box(int y,const char*label,const char*v,int idx,int width=438){text(pix,W,H,30,y,label,0x0098a7b3,1);rr(30,y+18,width,42,7,field==idx?0x00324552:0x001d2730);text(pix,W,H,44,y+33,v,0x00edf2f6,1);if(field==idx)rect(pix,W,H,44+(i32)slen(v)*6,y+31,2,12,0x006aa9e9);}
static void draw(){fill(pix,W*H,0x0011161a);rect(pix,W,H,0,0,W,60,0x00252a30);text(pix,W,H,24,18,"PEBBLE",0x00f3f5f6,2);text(pix,W,H,132,23,"FIND THE SMALL THINGS THAT STEAL YOUR TIME",0x009aa5ad,1);
box(82,"WHAT JUST GOT IN YOUR WAY?",friction,0);box(154,"WHERE / WHEN DID IT HAPPEN?",context,1);box(226,"MINUTES LOST (ESTIMATE)",minutes,2,190);box(298,"WHAT WOULD REMOVE THIS FRICTION?",fixidea,3);rr(30,386,210,42,7,0x003b7557);text(pix,W,H,79,401,"LOG PEBBLE",0x00ffffff,1);text(pix,W,H,30,455,"ONE ANNOYANCE IS SMALL. REPEATED ANNOYANCES BECOME A SYSTEM PROBLEM.",0x007f8d96,1);
rr(494,78,258,414,9,0x001a222a);text(pix,W,H,512,96,"FRICTION DEBT",0x00e8edf1,1);char n[16];num(n,debt);text(pix,W,H,512,122,n,0x006fbe8a,2);text(pix,W,H,560,127,"MINUTES RECORDED",0x0089959e,1);num(n,entries);text(pix,W,H,512,154,n,0x00e8edf1,1);text(pix,W,H,536,154,"PEBBLES",0x0089959e,1);text(pix,W,H,512,184,"RECENT EVIDENCE",0x00e8edf1,1);int y=208;char line[38];u32 li=0,skip=0;for(u32 i=0;logbuf[i]&&y<472;i++){char c=logbuf[i];if(c=='\n'){line[li]=0;if(skip++>=(u32)scroll){text(pix,W,H,512,y,line,0x00b9c5cc,1);y+=15;}li=0;}else if(li<36)line[li++]=c;}sc(SYS_PRESENT,win,(u64)pix,(u64)W*H*4);dirty=false;}
static void key(char c){char*b=field==0?friction:field==1?context:field==2?minutes:fixidea;u32*n=field==0?&fl:field==1?&cl:field==2?&ml:&xl;u32 cap=field==0?98:field==1?88:field==2?6:98;if(c=='\b'){if(*n)b[--(*n)]=0;}else if(c=='\n'){field=(field+1)%4;}else if(c>=32&&c<127&&*n<cap&&(field!=2||(c>='0'&&c<='9'))){b[(*n)++]=c;b[*n]=0;}dirty=true;}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);if(!pix)sc(0,1);win=makeWindow(events,W,H,110,62);if(!win)sc(0,2);load();for(;;){Wire m{};while(sc(SYS_IPC_RECV,events,(u64)&m)>0){if(m.type==KEY&&m.bytes==sizeof(KeyEv)){auto*k=(KeyEv*)m.payload;key((char)k->codepoint);}else if(m.type==POINTER&&m.bytes==sizeof(PtrEv)){auto*p=(PtrEv*)m.payload;if(p->flags&1){if(p->x>=30&&p->x<470){if(p->y>=100&&p->y<142)field=0;else if(p->y>=172&&p->y<214)field=1;else if(p->y>=244&&p->y<286)field=2;else if(p->y>=316&&p->y<358)field=3;else if(p->y>=386&&p->y<428)save();dirty=true;}}}else if(m.type==CLOSE)sc(0,0);}if(dirty)draw();sc(SYS_YIELD);}}
